/**
 * Drag and drop utilities for Kanban board using @dnd-kit/core
 */

import { DragEndEvent } from '@dnd-kit/core';

export const handleDragEnd = (
  event: DragEndEvent,
  onTaskMove: (
    taskId: string,
    newStatus: 'Todo' | 'In Progress' | 'Done' | 'Next Version'
  ) => void
) => {
  const { active, over } = event;

  console.log('Drag end event:', event); // Debug log

  // If dropped outside any droppable area
  if (!over) {
    console.log('No drop target - drag cancelled');
    return;
  }

  // If dropped in the same position
  if (active.id === over.id) {
    console.log('Same position - no change needed');
    return;
  }

  // Find the target column
  const targetColumn = KANBAN_COLUMNS.find(
    (col) => col.id === over.id
  );

  if (targetColumn) {
    // Extract task ID from active.id (format: "task-{taskId}")
    const taskId = active.id.toString().replace('task-', '');
    console.log(`Moving task ${taskId} to ${targetColumn.status}`); // Debug log
    onTaskMove(taskId, targetColumn.status);
  }
};

'use client';

import React from 'react';
import { DragEndEvent, DndContext, DragOverlay, closestCorners } from '@dnd-kit/core';
import KanbanColumn from '@/components/Kanban/KanbanColumn';
import useProjectStore from '@/store/useProjectStore';
import { handleDragEnd, KANBAN_COLUMNS } from '@/utils/dragAndDrop';

export default function KanbanBoard({ projectId }: KanbanBoardProps) {
  const moveTask = useProjectStore((state) => state.moveTask);

  if (!projectId) return null;

  const onDragEnd = (event: DragEndEvent) => {
    handleDragEnd(event, (taskId, newStatus) => {
      moveTask(taskId, newStatus);
    });
  };

  return (
    <DndContext onDragEnd={onDragEnd} collisionDetection={closestCorners}>
      <div className="flex-1 p-6 bg-slate-900">
        <div className="flex space-x-4 h-full">
          {KANBAN_COLUMNS.map((column, index) => (
            <KanbanColumn
              key={column.id}
              title={column.title}
              projectId={projectId}
              status={column.status}
              columnId={column.id}
              description={getColumnDescription(column.status)}
              color={getColumnColor(index)}
            />
          ))}
        </div>
      </div>
    </DndContext>
  );

