import { useDroppable } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { Plus, MoreHorizontal, Circle } from 'lucide-react';
import CreateTaskForm from '../forms/CreateTaskForm';
import DragItem from './DragItem';
import useProjectStore from '@/store/useProjectStore';

export default function KanbanColumn({
  title,
  projectId,
  status,
  columnId,
  description,
  color,
}: KanbanColumnProps) {
  const [showCreateTask, setShowCreateTask] = useState(false);
  const allTasks = useProjectStore((state) => state.tasks);
  const allTeamMembers = useProjectStore((state) => state.teamMembers);

  const { setNodeRef, isOver } = useDroppable({
    id: columnId,
  });

  const tasks = allTasks.filter(
    (task) => task.projectId === projectId && task.status === status
  );
  const teamMembers = allTeamMembers.filter(
    (member) => member.projectId === projectId
  );

  const taskIds = tasks.map((task) => `task-${task.id}`);

  const count = tasks.length;
  const estimate = tasks.reduce((sum, task) => sum + task.estimate, 0);

{/* Column Content */}
<div
  ref={setNodeRef}
  className={`min-h-96 border-l-2 border-r-2 border-dashed ${
    colorClasses.border
  } ${colorClasses.bg} px-4 py-2 ${
    isOver ? 'bg-slate-700/50' : ''
  }`}
>
  <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
    {/* Task Items */}
    <div className="space-y-3 mb-4">
      {tasks.map((task) => {
        const assignee = teamMembers.find(
          (member) => member.id === task.assigneeId
        );
        return (
          <DragItem
            key={task.id}
            task={task}
            assignee={assignee}
          />
        );
      })}
    </div>
  </SortableContext>

  {tasks.length === 0 && (
    <div className="text-center py-8">
      <p className="text-slate-500 text-sm mb-4">No items yet</p>
    </div>
  )}

  {/* Add Item Button */}
  <button
    onClick={() => setShowCreateTask(true)}
    className="w-full flex items-center justify-center space-x-2 py-3 text-slate-400 hover:text-slate-300 hover:bg-slate-800/50 rounded-md transition-colors"
  >
    <Plus className="w-4 h-4" />
    <span className="text-sm">Add item</span>
  </button>
</div>

'use client';

import React, { useState } from 'react';
import { DragEndEvent, DndContext, closestCorners } from '@dnd-kit/core';
import KanbanColumn from '@/components/Kanban/KanbanColumn';
import useProjectStore from '@/store/useProjectStore';
import { handleDragEnd, KANBAN_COLUMNS } from '@/utils/dragAndDrop';

interface KanbanBoardProps {
  projectId: string;
}

export default function KanbanBoard({ projectId }: KanbanBoardProps) {
  const moveTask = useProjectStore((state) => state.moveTask);
  const [activeTab, setActiveTab] = useState(0);

  if (!projectId) return null;

  const onDragEnd = (event: DragEndEvent) => {
    handleDragEnd(event, (taskId, newStatus) => {
      moveTask(taskId, newStatus);
    });
  };

  return (
    <>
      {/* Mobile Tab View */}
      <div className="block lg:hidden">
        <div className="flex-1 p-4 bg-slate-900">
          {/* Tab Headers */}
          <div className="flex space-x-1 mb-4 bg-slate-800 p-1 rounded-lg">
            {KANBAN_COLUMNS.map((column, index) => (
              <button
                key={column.id}
                onClick={() => setActiveTab(index)}
                className={`flex-1 py-2 px-3 text-sm font-medium rounded-md transition-colors ${
                  activeTab === index
                    ? 'bg-slate-700 text-white'
                    : 'text-slate-400 hover:text-slate-300'
                }`}
              >
                {column.title}
              </button>
            ))}
          </div>

          {/* Active Tab Content */}
          <div className="min-h-[500px]">
            <MobileKanbanColumn
              title={KANBAN_COLUMNS[activeTab].title}
              projectId={projectId}
              status={KANBAN_COLUMNS[activeTab].status}
              columnId={KANBAN_COLUMNS[activeTab].id}
              description={getColumnDescription(KANBAN_COLUMNS[activeTab].status)}
              color={getColumnColor(activeTab)}
            />
          </div>
        </div>
      </div>

      {/* Desktop Drag & Drop View */}
      <div className="hidden lg:block">
        <DndContext onDragEnd={onDragEnd} collisionDetection={closestCorners}>
          <div className="flex-1 p-6 bg-slate-900">
            <div className="flex space-x-4 h-full">
              {KANBAN_COLUMNS.map((column, index) => (
                <KanbanColumn
                  key={column.id}
                  title={column.title}
                  projectId={projectId}
                  status={column.status}
                  columnId={column.id}
                  description={getColumnDescription(column.status)}
                  color={getColumnColor(index)}
                />
              ))}
            </div>
          </div>
        </DndContext>
      </div>
    </>
  );

